module Shingles = struct
  let create_table db =
    U.exec db
      {|
        CREATE TABLE IF NOT EXISTS "shingles" (
          shingle BLOB    NOT NULL,
          doc_id  INTEGER NOT NULL REFERENCES documents(doc_id),
          "start" INTEGER NOT NULL,
          "end"   INTEGER NOT NULL,
          PRIMARY KEY (doc_id, "start")
        )
      |};
    U.exec db
      {|CREATE INDEX IF NOT EXISTS "shingles_shingle" ON "shingles" (shingle)|}




  let col_find_doc_id = 0
  let col_find_start = 1
  let col_find_end = 2

  let add db ~(doc_id : T.doc_id) ~(shingle : Internal_types.shingle_str)
      ~(range : T.range) =
    U.exec_params db
      {|INSERT OR REPLACE INTO "shingles" (shingle, doc_id, "start", "end")
        VALUES (?, ?, ?, ?)|}
      [
        U.Blob (shingle :> string);
        U.Int64 (A.Doc_id.to_int64 doc_id);
        U.Int64 (Int64.of_int range.start);
        U.Int64 (Int64.of_int range.end_);
      ]

  let find db (shingle : Internal_types.shingle_str) :
      (T.doc_id * T.range) list =
    U.query_rows db
      {|SELECT doc_id, "start", "end" FROM "shingles" WHERE shingle = ?|}
      [ U.Blob (shingle :> string) ]
      ~f:(fun stmt ->
        ( A.Doc_id.of_int64_exn (Sqlite3.column_int64 stmt col_find_doc_id),
          ({
             start = Int64.to_int (Sqlite3.column_int64 stmt col_find_start);
             end_ = Int64.to_int (Sqlite3.column_int64 stmt col_find_end);
           }
            : T.range) ))

  let delete_doc db (doc_id : T.doc_id) =
    U.exec_params db {|DELETE FROM "shingles" WHERE doc_id = ?|}
      [ U.Int64 (A.Doc_id.to_int64 doc_id) ]
end

module Anchors = struct
  let create_table db =
    U.exec db
      {|
        CREATE TABLE IF NOT EXISTS "anchors" (
          anchor_id            INTEGER PRIMARY KEY AUTOINCREMENT,
          doc_id               INTEGER NOT NULL REFERENCES documents(doc_id),
          doc_revision         INTEGER NOT NULL,
          doc_revision_attempt INTEGER NOT NULL,
          "start"              INTEGER NOT NULL,
          "end"                INTEGER NOT NULL,
          last_author          TEXT    NOT NULL,
          raw_contents         BLOB    NOT NULL,
          acknowledged_revision INTEGER
        )
      |};
    U.exec db
      {|CREATE INDEX IF NOT EXISTS "anchors_doc_id" ON "anchors" (doc_id)|};
    U.exec db
      {|CREATE INDEX IF NOT EXISTS "anchors_start" ON "anchors" ("start")|};
    U.exec db
      {|CREATE INDEX IF NOT EXISTS "anchors_end" ON "anchors" ("end")|};
    U.exec db
      {|CREATE INDEX IF NOT EXISTS "anchors_doc_id_attempt"
        ON "anchors" (doc_id, doc_revision_attempt)|}



  let col_anchor_id = 0
  let col_doc_id = 1
  let col_doc_revision = 2
  let col_doc_revision_attempt = 3
  let col_start = 4
  let col_end = 5
  let col_last_author = 6
  let col_raw_contents = 7
  let col_acknowledged_revision = 8

  let int_option_of_column stmt i : int option =
    match Sqlite3.column stmt i with
    | Sqlite3.Data.NULL -> None
    | Sqlite3.Data.INT n -> Some (Int64.to_int n)
    | _ ->
        ksprintf failwith
          "internal error: unexpected SQLite storage class for \
           \"anchors\".acknowledged_revision at row %d"
          i

  let param_of_int_option opt_n =
    match opt_n with
    | Some n -> U.Nullable_int64 (Some (Int64.of_int n))
    | None -> U.Nullable_int64 None

  let row_to_anchor stmt : Internal_types.anchor =
    {
      anchor_id =
        A.Anchor_id.of_int64_exn (Sqlite3.column_int64 stmt col_anchor_id);
      doc_id = A.Doc_id.of_int64_exn (Sqlite3.column_int64 stmt col_doc_id);
      doc_revision = Int64.to_int (Sqlite3.column_int64 stmt col_doc_revision);
      doc_revision_attempt =
        Int64.to_int (Sqlite3.column_int64 stmt col_doc_revision_attempt);
      range =
        {
          start = Int64.to_int (Sqlite3.column_int64 stmt col_start);
          end_ = Int64.to_int (Sqlite3.column_int64 stmt col_end);
        };
      last_author =
        author_of_string (Sqlite3.column_text stmt col_last_author);
      raw_contents = Sqlite3.column_blob stmt col_raw_contents;
      acknowledged_revision =
        int_option_of_column stmt col_acknowledged_revision;
    }

  let select_cols =
    {|anchor_id, doc_id, doc_revision, doc_revision_attempt,
      "start", "end", last_author, raw_contents, acknowledged_revision|}

  let create db (a : Internal_types.anchor) : Internal_types.anchor =
    let anchor_id =
      exec_returning_one db
        {|INSERT INTO "anchors"
            (doc_id, doc_revision, doc_revision_attempt,
             "start", "end", last_author, raw_contents,
             acknowledged_revision)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?)
          RETURNING anchor_id|}
        [
          U.Int64 (A.Doc_id.to_int64 a.doc_id);
          U.Int64 (Int64.of_int a.doc_revision);
          U.Int64 (Int64.of_int a.doc_revision_attempt);
          U.Int64 (Int64.of_int a.range.start);
          U.Int64 (Int64.of_int a.range.end_);
          U.Text (Util.Text.validate_exn (author_to_string a.last_author));
          U.Blob a.raw_contents;
          param_of_int_option a.acknowledged_revision;
        ]
        ~f:(fun stmt ->
          A.Anchor_id.of_int64_exn (Sqlite3.column_int64 stmt 0))
    in
    { a with Internal_types.anchor_id }

  let get db (anchor_id : T.anchor_id) : Internal_types.anchor option =
    U.query_rows db
      (sprintf {|SELECT %s FROM "anchors" WHERE anchor_id = ?|} select_cols)
      [ U.Int64 (A.Anchor_id.to_int64 anchor_id) ]
      ~f:row_to_anchor
    |> function
    | [] -> None
    | x :: _ -> Some x

  let delete db (anchor_id : T.anchor_id) =
    U.exec_params db {|DELETE FROM "anchors" WHERE anchor_id = ?|}
      [ U.Int64 (A.Anchor_id.to_int64 anchor_id) ]

  let relocate db (a : Internal_types.anchor) =
    U.exec_params db
      {|UPDATE "anchors"
        SET doc_id = ?, doc_revision = ?, doc_revision_attempt = ?,
            "start" = ?, "end" = ?, last_author = ?, raw_contents = ?
        WHERE anchor_id = ?|}
      [
        U.Int64 (A.Doc_id.to_int64 a.doc_id);
        U.Int64 (Int64.of_int a.doc_revision);
        U.Int64 (Int64.of_int a.doc_revision_attempt);
        U.Int64 (Int64.of_int a.range.start);
        U.Int64 (Int64.of_int a.range.end_);
        U.Text (Util.Text.validate_exn (author_to_string a.last_author));
        U.Blob a.raw_contents;
        U.Int64 (A.Anchor_id.to_int64 a.anchor_id);
      ]

  let mark_attempt_failed db (anchor_id : T.anchor_id) ~doc_revision_attempt =
    U.exec_params db
      {|UPDATE "anchors" SET doc_revision_attempt = ? WHERE anchor_id = ?|}
      [
        U.Int64 (Int64.of_int doc_revision_attempt);
        U.Int64 (A.Anchor_id.to_int64 anchor_id);
      ]

  let acknowledge db (anchor_id : T.anchor_id) ~revision =
    U.exec_params db
      {|UPDATE "anchors" SET acknowledged_revision = ? WHERE anchor_id = ?|}
      [
        U.Int64 (Int64.of_int revision);
        U.Int64 (A.Anchor_id.to_int64 anchor_id);
      ]

  let get_overlapping db (doc_id : T.doc_id) ~start ~end_ :
      Internal_types.anchor list =
    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_id = ? AND "start" < ? AND "end" > ?|}
         select_cols)
      [
        U.Int64 (A.Doc_id.to_int64 doc_id);
        U.Int64 (Int64.of_int end_);
        U.Int64 (Int64.of_int start);
      ]
      ~f:row_to_anchor
  let cat = [ "Shingles"; "borderline relocation" ] in


  let widen_interior_spaces s ~guard =
    let n = String.length s in
    let core_start = min guard n in
    let core_end = max core_start (n - guard) in
    let before = String.sub s 0 core_start in
    let core = String.sub s core_start (core_end - core_start) in
    let after = String.sub s core_end (n - core_end) in
    let widened_core = String.concat "   " (String.split_on_char ' ' core) in
    before ^ widened_core ^ after
  in





  let scatter_edits s ~period ~replacement =
    String.mapi (fun i c -> if i mod period = 0 then replacement else c) s
  in
  [
    Testo.create ~category:cat
      "TRUE POSITIVE: a pure whitespace-only edit inside an anchor's own \
       span (every interior single space widened to three) still relocates, \
       thanks to whitespace normalization" (fun () ->
        let target = String.sub big_text 0 80 in
        let files =
          make_files [ ("a.ml", junk 'A' 30 ^ target ^ junk 'B' 30) ]
        in
        with_declared_test_db files (fun store ->
            ignore
              (snd
                 (Text.add_file store (source_doc "a.ml")
                    (source files "a.ml"))
                : Text.anchor list);
            let anchor =
              Text.add_anchor store (source_doc "a.ml") (source files "a.ml")
                ~expected_revision:0 ~start:30
                ~end_:(30 + String.length target)
            in
            let widened = widen_interior_spaces target ~guard:8 in
            Hashtbl.replace files "a.ml" (junk 'A' 30 ^ widened ^ junk 'B' 30);
            let _, changed =
              Text.add_file store (source_doc "a.ml") (source files "a.ml")
            in
            match find_by_id changed anchor.anchor_id with
            | None ->
                fail
                  "expected the anchor to be reported as changed (its raw \
                   byte span grew, even though the underlying text is the \
                   same once whitespace is collapsed)"
            | Some a ->
                Testo.check ~msg:"same text once whitespace is collapsed"
                  Testo.string (strip_whitespace target)
                  (strip_whitespace a.raw_contents)));
    Testo.create ~category:cat
      "TRUE NEGATIVE: a full rewrite of similar length and shape correctly \
